78: pub fn main() -> Result<(), std::io::Error> {
79:   let cli_args = CliArgs::parse();
80:   let project_root = std::env::current_dir()?;
81: 
82:   // If we're given an input file, read from it and adjust its name.
83:   //
84:   // If we're not given an input file and stdin was redirected, read
85:   // from it and create a fake name. Return an error if stdin was not
86:   // redirected (otherwise the program will hang waiting for input).
87:   //
88:   let inputs = if !cli_args.input_file.is_empty() {
89:     if cli_args.input_file.len() > 1 && cli_args.output_file.is_some() {
90:       eprintln!("Cannot use the --output-file option with multiple inputs. Use --output-dir instead.");
91:       std::process::exit(1);
92:     }
93: 
94:     if cli_args.input_file.len() > 1 && cli_args.output_file.is_none() && cli_args.output_dir.is_none() {
95:       eprintln!("Cannot output to stdout with multiple inputs. Use --output-dir instead.");
96:       std::process::exit(1);
97:     }
98: 
99:     cli_args
100:       .input_file
101:       .into_iter()
102:       .map(|ref f| -> Result<_, std::io::Error> {
103:         let absolute_path = fs::canonicalize(f)?;
104:         let filename = pathdiff::diff_paths(absolute_path, &project_root).unwrap();
105:         let filename = filename.to_string_lossy().into_owned();
106:         let contents = fs::read_to_string(f)?;
107:         Ok((filename, contents))
108:       })
109:       .collect::<Result<_, _>>()?
110:   } else {
111:     // Don't silently wait for input if stdin was not redirected.
112:     let stdin = io::stdin();
113:     if stdin.is_terminal() {
114:       return Err(io::Error::new(
115:         io::ErrorKind::Other,
116:         "Not reading from stdin as it was not redirected",
117:       ));
118:     }
119:     let filename = format!("stdin-{}", std::process::id());
120:     let contents = io::read_to_string(stdin)?;
121:     vec![(filename, contents)]
122:   };
123: 
124:   let css_modules = if let Some(_) = cli_args.css_modules {
125:     let pattern = if let Some(pattern) = cli_args.css_modules_pattern.as_ref() {
126:       match lightningcss::css_modules::Pattern::parse(pattern) {
127:         Ok(p) => p,
128:         Err(e) => {
129:           eprintln!("{}", e);
130:           std::process::exit(1);
131:         }
132:       }
133:     } else {
134:       Default::default()
135:     };
136: 
137:     Some(lightningcss::css_modules::Config {
138:       pattern,
139:       dashed_idents: cli_args.css_modules_dashed_idents,
140:       ..Default::default()
141:     })
142:   } else {
143:     cli_args.css_modules.as_ref().map(|_| Default::default())
144:   };
145: 
146:   let fs = FileProvider::new();
147: 
148:   for (filename, source) in inputs {
149:     let warnings = if cli_args.error_recovery {
150:       Some(Arc::new(RwLock::new(Vec::new())))
151:     } else {
152:       None
153:     };
154: 
155:     let mut source_map = if cli_args.sourcemap {
156:       Some(SourceMap::new(&project_root.to_string_lossy()))
157:     } else {
158:       None
159:     };
160: 
161:     let output_file = if let Some(output_file) = &cli_args.output_file {
162:       Some(Cow::Borrowed(Path::new(output_file)))
163:     } else if let Some(dir) = &cli_args.output_dir {
164:       Some(Cow::Owned(
165:         Path::new(dir).join(Path::new(&filename).file_name().unwrap()),
166:       ))
167:     } else {
168:       None
169:     };
170: 
171:     let res = {
172:       let mut flags = ParserFlags::empty();
173:       flags.set(ParserFlags::CUSTOM_MEDIA, cli_args.custom_media);
174:       flags.set(
175:         ParserFlags::SCROLL_NAVIGATION_CONTROLS,
176:         cli_args.scroll_navigation_controls,
177:       );
178: 
179:       let mut options = ParserOptions {
180:         flags,
181:         css_modules: css_modules.clone(),
182:         error_recovery: cli_args.error_recovery,
183:         warnings: warnings.clone(),
184:         ..ParserOptions::default()
185:       };
186: 
187:       let mut stylesheet = if cli_args.bundle {
188:         let mut bundler = Bundler::new(&fs, source_map.as_mut(), options);
189:         bundler.bundle(Path::new(&filename)).unwrap()
190:       } else {
191:         if let Some(sm) = &mut source_map {
192:           sm.add_source(&filename);
193:           let _ = sm.set_source_content(0, &source);
194:         }
195:         options.filename = filename;
196:         StyleSheet::parse(&source, options).unwrap()
197:       };
198: 
199:       let targets = if !cli_args.targets.is_empty() {
200:         Browsers::from_browserslist(&cli_args.targets).unwrap()
201:       } else if cli_args.browserslist {
202:         Browsers::load_browserslist().unwrap()
203:       } else {
204:         None
205:       }
206:       .into();
207: 
208:       stylesheet
209:         .minify(MinifyOptions {
210:           targets,
211:           ..MinifyOptions::default()
212:         })
213:         .unwrap();
214: 
215:       stylesheet
216:         .to_css(PrinterOptions {
217:           minify: cli_args.minify,
218:           source_map: source_map.as_mut(),
219:           project_root: Some(&project_root.to_string_lossy()),
220:           targets,
221:           ..PrinterOptions::default()
222:         })
223:         .unwrap()
224:     };
225: 
226:     let map = if let Some(ref mut source_map) = source_map {
227:       let mut vlq_output: Vec<u8> = Vec::new();
228:       source_map
229:         .write_vlq(&mut vlq_output)
230:         .map_err(|_| io::Error::new(io::ErrorKind::Other, "Error writing sourcemap vlq"))?;
231: 
232:       let sm = SourceMapJson {
233:         version: 3,
234:         mappings: unsafe { String::from_utf8_unchecked(vlq_output) },
235:         sources: source_map.get_sources(),
236:         sources_content: source_map.get_sources_content(),
237:         names: source_map.get_names(),
238:       };
239: 
240:       serde_json::to_vec(&sm).ok()
241:     } else {
242:       None
243:     };
244: 
245:     if let Some(warnings) = warnings {
246:       let warnings = Arc::try_unwrap(warnings).unwrap().into_inner().unwrap();
247:       for warning in warnings {
248:         eprintln!("{}", warning);
249:       }
250:     }
251: 
252:     if let Some(output_file) = &output_file {
253:       let mut code = res.code;
254:       if cli_args.sourcemap {
255:         if let Some(map_buf) = map {
256:           let map_filename = output_file.to_string_lossy() + ".map";
257:           code += &format!("\n/*# sourceMappingURL={} */\n", map_filename);
258:           fs::write(map_filename.as_ref(), map_buf)?;
259:         }
260:       }
261: 
262:       if let Some(p) = output_file.parent() {
263:         fs::create_dir_all(p)?
264:       };
265:       fs::write(output_file, code.as_bytes())?;
266: 
267:       if let Some(css_modules) = &cli_args.css_modules {
268:         let css_modules_filename = if let Some(name) = css_modules {
269:           Cow::Borrowed(name)
270:         } else {
271:           Cow::Owned(infer_css_modules_filename(output_file.as_ref())?)
272:         };
273:         if let Some(exports) = res.exports {
274:           let css_modules_json = serde_json::to_string(&exports)?;
275:           fs::write(css_modules_filename.as_ref(), css_modules_json)?;
276:         }
277:       }
278:     } else {
279:       if let Some(exports) = res.exports {
280:         println!(
281:           "{}",
282:           serde_json::json!({
283:             "code": res.code,
284:             "exports": exports
285:           })
286:         );
287:       } else {
288:         println!("{}", res.code);
289:       }
290:     }
291:   }
292: 
293:   Ok(())
294: }
