296: fn infer_css_modules_filename(path: &Path) -> Result<String, std::io::Error> {
297:   if path.extension() == Some(ffi::OsStr::new("json")) {
298:     Err(io::Error::new(
299:       io::ErrorKind::Other,
300:       "Cannot infer a css modules json filename, since the output file extension is '.json'",
301:     ))
302:   } else {
303:     // unwrap: the filename option is a String from clap, so is valid utf-8
304:     Ok(path.with_extension("json").to_str().unwrap().into())
305:   }
306: }

